// A tiny shop
"use strict";

const { ActionRowBuilder, ButtonBuilder, ButtonStyle, Client, ComponentType, Events, GatewayIntentBits, MessageFlags, SlashCommandBuilder } = require("discord.js");
const { DatabaseSync } = require("node:sqlite");
const { checkInt, mul, neg, sub, toStr } = require("./newr_rt.js");
const shop_items = require("./shop_items.js");

const _DEFAULT_LOCALE = "en";
const STRINGS = {
  "en": {
    "buy.ok": "Bought {item} for {price} gold. Balance: {balance}.",
    "buy.poor": "Not enough gold — {item} costs {price}, you have {balance}.",
  },
  "id": {
    "buy.ok": "Membeli {item} seharga {price} gold. Saldo: {balance}.",
    "buy.poor": "Gold tidak cukup — {item} harganya {price}, kamu punya {balance}.",
  },
};


function _t(key, locale, vars = {}) {
  const loc = (typeof locale === "string" ? locale : null) || _DEFAULT_LOCALE;
  const template = (STRINGS[loc] || STRINGS[loc.split("-")[0]]
    || STRINGS[_DEFAULT_LOCALE] || {})[key];
  if (template === undefined) {
    return key;
  }
  return template.replace(/\{(\w+)\}/g, (_m, name) => toStr(vars[name] ?? null));
}

const componentHandlers = new Map([
  ["buy-again", async (interaction) => {
    await interaction.reply({ content: `Use /buy again, ${interaction.user.mention}!` });
  }],
]);


class Bot extends Client {
  constructor() {
    super({ intents: [GatewayIntentBits.Guilds, GatewayIntentBits.GuildMembers] });
    this.economy_db = null;
  }

  async setup() {
    await this._economy_connect();
  }

  async _economy_connect() {
    this.economy_db = new DatabaseSync("economy.db");
    this.economy_db.exec("PRAGMA busy_timeout = 5000");
    this.economy_db.exec("CREATE TABLE IF NOT EXISTS balances (user TEXT PRIMARY KEY, balance TEXT)");
    this.economy_db.exec("CREATE TABLE IF NOT EXISTS ledger (id INTEGER PRIMARY KEY AUTOINCREMENT, user TEXT NOT NULL, amount TEXT NOT NULL, key TEXT UNIQUE, created_at INTEGER NOT NULL)");
  }

  async economy_balance(userId) {
    const row = this.economy_db.prepare("SELECT balance FROM balances WHERE user = ?").get(userId);
    return row ? BigInt(row.balance) : 0n;
  }

  async _economy_apply(userId, amount, key) {
    // Idempotent on key: a duplicate key is a replay,
    // not an error (P11). One explicit transaction:
    // the balance + ledger land together or not at all.
    // node:sqlite is synchronous and single-threaded,
    // so no lock is needed — no interleaving is possible.
    if (key !== null && key !== undefined) {
      const dup = this.economy_db.prepare("SELECT 1 FROM ledger WHERE key = ?").get(key);
      if (dup) {
        return;
      }
    }
    this.economy_db.exec("BEGIN IMMEDIATE");
    try {
      const row = this.economy_db.prepare("SELECT balance FROM balances WHERE user = ?").get(userId);
      const cur = row ? BigInt(row.balance) : 0n;
      const next = checkInt(cur + amount);
      this.economy_db.prepare("INSERT INTO balances (user, balance) VALUES (?, ?) ON CONFLICT(user) DO UPDATE SET balance = excluded.balance").run(userId, next.toString());
      this.economy_db.prepare("INSERT INTO ledger (user, amount, key, created_at) VALUES (?, ?, ?, ?)").run(userId, amount.toString(), key, Math.floor(Date.now() / 1000));
      this.economy_db.exec("COMMIT");
    } catch (e) {
      this.economy_db.exec("ROLLBACK");
      throw e;
    }
  }

  async economy_credit(userId, amount, key = null) {
    await this._economy_apply(userId, amount, key);
  }

  async economy_debit(userId, amount, key = null) {
    // The balance check is inside the transaction (no
    // TOCTOU): a concurrent debit cannot slip between
    // the check and the write. A replayed key returns
    // true — the debit already happened.
    if (key !== null && key !== undefined) {
      const dup = this.economy_db.prepare("SELECT 1 FROM ledger WHERE key = ?").get(key);
      if (dup) {
        return true;
      }
    }
    this.economy_db.exec("BEGIN IMMEDIATE");
    try {
      const row = this.economy_db.prepare("SELECT balance FROM balances WHERE user = ?").get(userId);
      const cur = row ? BigInt(row.balance) : 0n;
      if (cur < amount) {
        this.economy_db.exec("ROLLBACK");
        return false;
      }
      const next = cur - amount;
      this.economy_db.prepare("INSERT INTO balances (user, balance) VALUES (?, ?) ON CONFLICT(user) DO UPDATE SET balance = excluded.balance").run(userId, next.toString());
      this.economy_db.prepare("INSERT INTO ledger (user, amount, key, created_at) VALUES (?, ?, ?, ?)").run(userId, (-amount).toString(), key, Math.floor(Date.now() / 1000));
      this.economy_db.exec("COMMIT");
    } catch (e) {
      this.economy_db.exec("ROLLBACK");
      throw e;
    }
    return true;
  }

  async economy_transfer(fromId, toId, amount, key = null) {
    // Both legs + the ledger in ONE transaction. A retry
    // heals a partial transfer: each leg is topped up
    // to its intended total (the out-leg debits `amount`,
    // the in-leg credits `amount`), so no money is
    // created or destroyed however the first attempt
    // died — a crash between the legs, or a poisoned
    // ledger row. The leg amounts are read from the
    // ledger (not just presence) and summed in JS with
    // BigInt — never SQL SUM, which would lose precision
    // on TEXT amounts (J9). The leg upserts are computed
    // in JS for the same reason (SQLite `+` on TEXT
    // would go through REAL arithmetic).
    let outDone = 0n;
    let inDone = 0n;
    if (key !== null && key !== undefined) {
      const outRows = this.economy_db.prepare("SELECT amount FROM ledger WHERE key = ?").all(key + ":out");
      const inRows = this.economy_db.prepare("SELECT amount FROM ledger WHERE key = ?").all(key + ":in");
      let outSum = 0n;
      let inSum = 0n;
      for (const r of outRows) { outSum += BigInt(r.amount); }
      for (const r of inRows) { inSum += BigInt(r.amount); }
      outDone = -outSum;
      inDone = inSum;
      if (outDone < 0n) { outDone = 0n; }
      if (outDone > amount) { outDone = amount; }
      if (inDone < 0n) { inDone = 0n; }
      if (inDone > amount) { inDone = amount; }
      if (outDone >= amount && inDone >= amount) {
        return true;
      }
    }
    const outLeft = amount - outDone;
    const inLeft = amount - inDone;
    this.economy_db.exec("BEGIN IMMEDIATE");
    try {
      if (outLeft > 0n) {
        const row = this.economy_db.prepare("SELECT balance FROM balances WHERE user = ?").get(fromId);
        const cur = row ? BigInt(row.balance) : 0n;
        if (cur < outLeft) {
          this.economy_db.exec("ROLLBACK");
          return false;
        }
        const next = cur - outLeft;
        this.economy_db.prepare("INSERT INTO balances (user, balance) VALUES (?, ?) ON CONFLICT(user) DO UPDATE SET balance = excluded.balance").run(fromId, next.toString());
        await this._ledgerUpsert(fromId, -outLeft, key === null || key === undefined ? null : key + ":out");
      }
      if (inLeft > 0n) {
        const row = this.economy_db.prepare("SELECT balance FROM balances WHERE user = ?").get(toId);
        const cur = row ? BigInt(row.balance) : 0n;
        const next = checkInt(cur + inLeft);
        this.economy_db.prepare("INSERT INTO balances (user, balance) VALUES (?, ?) ON CONFLICT(user) DO UPDATE SET balance = excluded.balance").run(toId, next.toString());
        await this._ledgerUpsert(toId, inLeft, key === null || key === undefined ? null : key + ":in");
      }
      this.economy_db.exec("COMMIT");
    } catch (e) {
      this.economy_db.exec("ROLLBACK");
      throw e;
    }
    return true;
  }

  async _ledgerUpsert(userId, amount, key) {
    // A ledger leg, upserted with JS-side arithmetic
    // (exact BigInt; see _transfer). Called only inside
    // a transaction held by the caller.
    if (key === null || key === undefined) {
      this.economy_db.prepare("INSERT INTO ledger (user, amount, key, created_at) VALUES (?, ?, ?, ?)").run(userId, amount.toString(), null, Math.floor(Date.now() / 1000));
      return;
    }
    const existing = this.economy_db.prepare("SELECT amount FROM ledger WHERE key = ?").get(key);
    if (existing) {
      const total = BigInt(existing.amount) + amount;
      this.economy_db.prepare("UPDATE ledger SET amount = ? WHERE key = ?").run(total.toString(), key);
    } else {
      this.economy_db.prepare("INSERT INTO ledger (user, amount, key, created_at) VALUES (?, ?, ?, ?)").run(userId, amount.toString(), key, Math.floor(Date.now() / 1000));
    }
  }

  async economy_get(table, key) {
    const row = this.economy_db.prepare(`SELECT * FROM ${table} WHERE user = ?`).get(key);
    if (!row) {
      return null;
    }
    return { user: row.user, balance: BigInt(row.balance) };
  }

  async economy_set(table, row) {
    const data = { ...row };
    const cols = Object.keys(data);
    const placeholders = cols.map(() => "?").join(", ");
    const updates = cols.map((c) => `${c} = excluded.${c}`).join(", ");
    const values = cols.map((key) => {
      let value = data[key];
      if (key === "balance") { value = value.toString(); }
      return value;
    });
    this.economy_db.prepare(`INSERT INTO ${table} (${cols.join(", ")}) VALUES (${placeholders}) ON CONFLICT(user) DO UPDATE SET ${updates}`).run(...values);
  }

  async economy_delete(table, key) {
    this.economy_db.prepare(`DELETE FROM ${table} WHERE user = ?`).run(key);
  }
}


const bot = new Bot();


const commands = [
  {
    data: new SlashCommandBuilder().setName("ping").setDescription("Answer with pong"),
    async execute(interaction) {
      await interaction.reply({ content: `Pong! Hello ${interaction.user.mention}` });
    },
  },
  {
    data: new SlashCommandBuilder().setName("buy").setDescription("Buy an item from the shop")
      .addStringOption((opt) => opt.setName("item").setDescription("item").setRequired(true).addChoices({ name: "brick", value: "brick" }, { name: "potion", value: "potion" }))
      .addIntegerOption((opt) => opt.setName("amount").setDescription("amount").setMinValue(1).setMaxValue(99)),
    async execute(interaction) {
      const item = interaction.options.getString("item", true);
      const amount = BigInt(interaction.options.getInteger("amount") ?? 1n);
      let price = mul(shop_items.price_of(item), amount);
      let bal = await bot.economy_balance(String(interaction.user.id));
      if (bal < price) {
        await interaction.reply({ content: _t("buy.poor", interaction.locale, {price: price, balance: bal, item: item}), flags: MessageFlags.Ephemeral });
      } else {
        await bot.economy_credit(String(interaction.user.id), neg(price), `buy-${interaction.user.id}-${item}-${amount}`);
        const _newr_c0_row = new ActionRowBuilder().addComponents(
          new ButtonBuilder().setCustomId("buy-again").setLabel("Buy again").setStyle(ButtonStyle.Primary));
        await interaction.reply({ content: _t("buy.ok", interaction.locale, {item: item, price: price, balance: sub(bal, price)}), components: [_newr_c0_row]});
        const _newr_c0_message = await interaction.fetchReply();
        const _newr_c0_collector = _newr_c0_message.createMessageComponentCollector({ componentType: ComponentType.Button, time: 60000 });
        _newr_c0_collector.on("collect", async (i) => {
          if (i.customId === "buy-again" && i.user.id !== interaction.user.id) {
            await i.reply({ content: "This button is not for you.", flags: MessageFlags.Ephemeral });
            return;
          }
          const handler = componentHandlers.get(i.customId);
          if (handler) {
            await handler(i);
          }
        });
        _newr_c0_collector.on("end", async (_collected, reason) => {
          if (reason === "time") {
            for (const child of _newr_c0_row.components) {
              child.setDisabled(true);
            }
            await _newr_c0_message.edit({ components: [_newr_c0_row] });
            await _newr_c0_message.edit({ content: "Offer expired." });
          }
        });
      }
    },
  },
  {
    data: new SlashCommandBuilder().setName("balance").setDescription("Show your balance"),
    async execute(interaction) {
      await interaction.reply({ content: `Balance: ${await bot.economy_balance(String(interaction.user.id))} gold.` });
    },
  },
];
const commandMap = new Map(commands.map((c) => [c.data.name, c]));


async function dispatchCommand(interaction, command) {
  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(`[dispatch] /${command.data.name} failed:`, error);
    const message = "Something went wrong running that command. Try again in a moment.";
    try {
      if (interaction.replied || interaction.deferred) {
        await interaction.followUp({ content: message, flags: MessageFlags.Ephemeral });
      } else {
        await interaction.reply({ content: message, flags: MessageFlags.Ephemeral });
      }
    } catch (replyError) {
      console.error("[dispatch] could not send the error reply:", replyError);
    }
  }
}


bot.on(Events.InteractionCreate, async (interaction) => {
  if (interaction.isChatInputCommand()) {
    const command = commandMap.get(interaction.commandName);
    if (!command) {
      return;
    }
    await dispatchCommand(interaction, command);
    return;
  }
  if (interaction.isButton() || interaction.isStringSelectMenu()) {
    const handler = componentHandlers.get(interaction.customId);
    if (!handler) {
      return;
    }
    await handler(interaction);
    return;
  }
  if (interaction.isModalSubmit()) {
    const handler = componentHandlers.get(interaction.customId);
    if (!handler) {
      return;
    }
    await handler(interaction);
    return;
  }
  if (interaction.isAutocomplete()) {
    const command = commandMap.get(interaction.commandName);
    if (!command || typeof command.autocomplete !== "function") {
      return;
    }
    await command.autocomplete(interaction);
    return;
  }
});


async function _every_1h() {
  console.info("Hourly shop check ran");
}


bot.once(Events.ClientReady, async (readyClient) => {
  console.info(`${readyClient.user.tag} is online`);
});


bot.on(Events.GuildMemberAdd, async (member) => {
  const channel = member.guild.systemChannel;
  if (channel !== null) {
    await channel.send({ content: `Welcome to ${member.guild.name}, ${member.mention}!` });
  }
});


async function main() {
  const token = process.env.DISCORD_TOKEN;
  if (!token) {
    throw new Error("set the DISCORD_TOKEN environment variable");
  }
  await bot.setup();
  await bot.login(token);
  setInterval(() => { _every_1h().catch((e) => console.error(e)); }, 3600000);
}


if (require.main === module) {
  main().catch((e) => {
    console.error(e);
    process.exit(1);
  });
}


module.exports = { bot, commands, commandMap, componentHandlers };
